#include "../tests/transfer_icon_scene.h"
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
static uint64_t region_hash(const uint8_t *pixels,unsigned column,float scale){
 nx_rect r=transfer_icon_bounds(column,0);unsigned sx=(unsigned)(r.x*scale),sy=(unsigned)(r.y*scale),side=(unsigned)(24*scale);
 uint64_t h=UINT64_C(14695981039346656037);
 for(unsigned y=sy;y<sy+side;++y)for(unsigned x=sx;x<sx+side;++x)for(unsigned c=0;c<4;++c)h=(h^pixels[(y*180+x)*4+c])*UINT64_C(1099511628211);
 return h;
}
int main(int argc,char **argv){
 if(argc!=2)return 2;nx_context *ui=NULL;if(nx_context_create(NULL,&ui)!=NX_OK)return 3;
 uint8_t pixels[180*140*4];const float scales[]={1,1.25f,1.5f,2};
 for(unsigned theme=1;theme<=4;++theme)for(unsigned density=0;density<4;++density)for(unsigned alpha=0;alpha<2;++alpha){
  nx_color clear;if(transfer_icon_scene(ui,(nx_theme_kind)theme,alpha?.55f:1,&clear))return 4;
  const nx_command *commands;size_t count;if(nx_frame_commands(ui,&commands,&count)!=NX_OK)return 5;
  nx_command *scaled=malloc(count*sizeof(*scaled));if(!scaled)return 6;transfer_icon_scale(commands,count,scales[density],scaled);
  nx_result result=nx_headless_render(scaled,count,pixels,180,140,720,clear);free(scaled);if(result!=NX_OK)return 7;
  char path[1024];snprintf(path,sizeof(path),"%s/t%u-d%u-a%u.rgba",argv[1],theme,density,alpha);
  FILE *file=fopen(path,"wb");if(!file)return 8;if(fwrite(pixels,1,sizeof(pixels),file)!=sizeof(pixels)||fclose(file))return 9;
  printf("{\"theme\":%u,\"density\":%.2f,\"alpha\":%u,\"transfer\":\"%016llx\",\"upload\":\"%016llx\",\"download\":\"%016llx\"}\n",theme,scales[density],alpha,(unsigned long long)region_hash(pixels,0,scales[density]),(unsigned long long)region_hash(pixels,1,scales[density]),(unsigned long long)region_hash(pixels,2,scales[density]));
 }
 nx_context_destroy(ui);return 0;
}

